describe('Sticky Footer Navigation on Mobile', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should display sticky footer navigation on mobile viewport', () => {
    cy.get('footer nav').should('be.visible');
    cy.get('footer nav').should('have.css', 'position', 'fixed');
    cy.get('footer nav').should('have.css', 'bottom', '0px');
    cy.get('footer nav').should('have.css', 'width', '100%');
  });

  it('should keep footer navigation visible when scrolling down the page', () => {
    cy.get('body').then(($body) => {
      const bodyHeight = $body.height();
      if (bodyHeight > cy.viewport().height) {
        cy.get('footer nav').then(($footer) => {
          const footerTop = $footer.offset().top;
          cy.scrollTo('bottom');
          cy.get('footer nav').should('be.visible');
          cy.get('footer nav').should('have.css', 'position', 'fixed');
        });
      }
    });
  });

  it('should have proper z-index to appear above page content', () => {
    cy.get('footer nav').should(($footer) => {
      const zIndex = window.getComputedStyle($footer[0]).zIndex;
      expect(parseInt(zIndex)).to.be.greaterThan(0);
    });
  });

  it('should display all navigation links in footer on mobile', () => {
    cy.get('footer nav a').should('have.length.greaterThan', 0);
    cy.get('footer nav a').each(($link) => {
      cy.wrap($link).should('be.visible');
      cy.wrap($link).should('have.attr', 'href');
    });
  });

  it('should not overlap main content when footer is sticky', () => {
    cy.get('main, [role="main"]').then(($main) => {
      const mainBottom = $main.offset().top + $main.height();
      cy.get('footer nav').then(($footer) => {
        const footerHeight = $footer.height();
        cy.get('main, [role="main"]').should('have.css', 'padding-bottom');
        const paddingBottom = window.getComputedStyle($main[0]).paddingBottom;
        expect(parseInt(paddingBottom)).to.be.greaterThanOrEqual(footerHeight);
      });
    });
  });

  it('should maintain footer navigation on landscape mobile orientation', () => {
    cy.viewport('iphone-x', 'landscape');
    cy.get('footer nav').should('be.visible');
    cy.get('footer nav').should('have.css', 'position', 'fixed');
    cy.get('footer nav').should('have.css', 'bottom', '0px');
  });

  it('should handle footer navigation with touch interactions', () => {
    cy.get('footer nav a').first().should('be.visible');
    cy.get('footer nav a').first().click();
    cy.url().should('not.equal', '/');
  });

  it('should not display sticky footer on desktop viewport', () => {
    cy.viewport(1920, 1080);
    cy.get('footer nav').then(($footer) => {
      const position = window.getComputedStyle($footer[0]).position;
      if (position === 'fixed') {
        cy.get('footer nav').should('have.css', 'position', 'fixed');
      }
    });
  });

  it('should handle edge case with very long footer navigation items', () => {
    cy.get('footer nav').should('be.visible');
    cy.get('footer nav a').each(($link) => {
      cy.wrap($link).should('be.visible');
      cy.wrap($link).should('have.css', 'overflow');
    });
  });
});
